// Home Assistant weather condition to icon; night picks the moon variants.
inline Icon from_condition(const std::string &c, bool night) {
  if (c == "clear-night") return CLEAR_NIGHT;
  if (c == "cloudy") return CLOUDY;
  if (c == "exceptional") return EXCEPTIONAL;
  if (c == "fog") return FOG;
  if (c == "hail") return HAIL;
  if (c == "lightning") return LIGHTNING;
  if (c == "lightning-rainy") return LIGHTNING_RAINY;
  if (c == "partlycloudy") return night ? PARTLYCLOUDY_NIGHT : PARTLYCLOUDY;
  if (c == "pouring") return POURING;
  if (c == "rainy") return RAINY;
  if (c == "snowy") return SNOWY;
  if (c == "snowy-rainy") return SNOWY_RAINY;
  if (c == "sunny") return night ? CLEAR_NIGHT : SUNNY;
  if (c == "windy") return WINDY;
  if (c == "windy-variant") return WINDY;
  return CLOUDY;
}

// Write frame `frame` (taken modulo the icon's frame count) into CGRAM
// slots first..first+3 as top-left, top-right, bottom-left, bottom-right.
template<typename LCD> inline void load(LCD *lcd, Icon icon, uint32_t frame, uint8_t first = 4) {
  const IconGlyphs &g = ICONS[icon < ICON_COUNT ? icon : CLOUDY];
  const uint8_t (*f)[8] = g.data[frame % g.frames];
  for (uint8_t c = 0; c < 4; c++) {
    uint8_t buf[8];
    memcpy(buf, f[c], 8);
    lcd->loadchar((first + c) & 7, buf);
  }
}

